CREATE TABLE `professional_units` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`public_id` CHAR(36) NOT NULL,`tenant_id` BIGINT UNSIGNED NOT NULL,`professional_id` BIGINT UNSIGNED NOT NULL,`unit_id` BIGINT UNSIGNED NOT NULL,`active` BOOLEAN NOT NULL DEFAULT TRUE,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE INDEX `professional_units_public_id_key` (`public_id`),UNIQUE INDEX `professional_units_professional_id_unit_id_key` (`professional_id`,`unit_id`),INDEX `professional_units_tenant_id_professional_id_active_idx` (`tenant_id`,`professional_id`,`active`),INDEX `professional_units_tenant_id_unit_id_active_idx` (`tenant_id`,`unit_id`,`active`),CONSTRAINT `professional_units_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `professional_units_professional_id_fkey` FOREIGN KEY (`professional_id`) REFERENCES `professionals`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `professional_units_unit_id_fkey` FOREIGN KEY (`unit_id`) REFERENCES `business_units`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
